if(shape==='chain')piece=`<g transform="rotate(-22 200 200)" filter="url(#${uid}d)">${Array.from({length:12},(_,i)=>{const a=i*Math.PI/6,x=200+105*Math.cos(a),y=215+78*Math.sin(a);return `<ellipse cx="${x}" cy="${y}" rx="26" ry="15" transform="rotate(${i*30+90} ${x} ${y})" fill="none" stroke="${m}" stroke-width="7"/>`}).join('')}</g>`;
